# 정적 분석 기준선(baseline) 비교 — (파일, 규칙, 함수) 로 같은 경고를 알아본다
baseline = {("can.c", "misra-c2012-10.4", "can_tx"), ("adc.c", "misra-c2012-11.4", "adc_init")}
suppressed = {("adc.c", "misra-c2012-11.4", "adc_init"): "DEV-012 레지스터 주소 변환, 검토 2026-10"}
today = [("can.c", "misra-c2012-10.4", "can_tx"), ("adc.c", "misra-c2012-11.4", "adc_init"),
         ("pwm.c", "misra-c2012-17.7", "pwm_set")]
for f in today:
    if f in suppressed: print("SUPPRESSED", f[0], f[1], "->", suppressed[f])
    elif f in baseline: print("BASELINE  ", f[0], f[1], "(고칠 목록)")
    else: print("NEW       ", f[0], f[1], "-> 빌드 실패")
# BASELINE   can.c misra-c2012-10.4 (고칠 목록)
# SUPPRESSED adc.c misra-c2012-11.4 -> DEV-012 레지스터 주소 변환, 검토 2026-10
# NEW        pwm.c misra-c2012-17.7 -> 빌드 실패

DLC = {**{i: i for i in range(9)}, 9: 12, 10: 16, 11: 20,
       12: 24, 13: 32, 14: 48, 15: 64}
def dlc_for(n):
    return min(d for d, b in DLC.items() if b >= n)
for n in (8, 9, 20, 33):
    d = dlc_for(n)
    print(f"payload {n:2d}B -> DLC {d:2d} ({DLC[d]}B, pad {DLC[d]-n})")
# payload  8B -> DLC  8 (8B, pad 0)
# payload  9B -> DLC  9 (12B, pad 3)
# payload 20B -> DLC 11 (20B, pad 0)
# payload 33B -> DLC 14 (48B, pad 15)
